function fireConfetti(container) {
  const colors = ["#1B6B45", "#1F3864", "#FFC94D", "#1E7A4C"];
  for (let i = 0; i < 24; i++) {
    const p = document.createElement("div");
    p.className = "confetti-piece";
    p.style.left = Math.random() * 100 + "%";
    p.style.background = colors[i % colors.length];
    p.style.animationDelay = (Math.random() * 0.3) + "s";
    p.style.borderRadius = Math.random() > 0.5 ? "50%" : "2px";
    container.appendChild(p);
    setTimeout(() => p.remove(), 1800);
  }
}

let parsedData = null, chartImages = null;
const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sept","Oct","Nov","Dec"];
const MONTH_NAMES_FULL = ["January","February","March","April","May","June","July","August","September","October","November","December"];

/* ---------- 0. Monthly / quarterly aggregation ---------- */
function computeMonthlyStats(daily) {
  const months = new Array(12).fill(null);
  daily.forEach(d => {
    const mi = d.date.getMonth();
    if (!months[mi]) months[mi] = { monthIdx: mi, year: d.date.getFullYear(), productionKwh: 0, expectedKwh: 0, estimatedKwh: 0, insolActualPoaWhm2: 0, insolEstPoaWhm2: 0, days: 0 };
    const rec = months[mi];
    rec.productionKwh += d["Production meter net energy"] || 0;
    rec.expectedKwh += d["Expected energy"] || 0;
    rec.estimatedKwh += d["Estimated Production"] || 0;
    rec.insolActualPoaWhm2 += d["POA"] || 0;
    rec.insolEstPoaWhm2 += d["Insolation estimate, POA"] || 0;
    rec.days++;
  });
  months.forEach(rec => {
    if (!rec) return;
    rec.actualMwh = rec.productionKwh / 1000;
    rec.expectedMwh = rec.expectedKwh / 1000;
    rec.estimatedMwh = rec.estimatedKwh / 1000;
    rec.actVsExp = rec.expectedMwh ? rec.actualMwh / rec.expectedMwh : 0;
    rec.actVsEst = rec.estimatedMwh ? rec.actualMwh / rec.estimatedMwh : 0;
    rec.actualInsolationKwhm2 = rec.insolActualPoaWhm2 / 1000;
    rec.estimatedInsolationKwhm2 = rec.insolEstPoaWhm2 / 1000;
    rec.insolationActVsEst = rec.estimatedInsolationKwhm2 ? rec.actualInsolationKwhm2 / rec.estimatedInsolationKwhm2 : 0;
  });
  return months;
}

function computeQuarterlyStats(monthly) {
  const quarters = [];
  for (let q = 0; q < 4; q++) {
    const qMonths = monthly.slice(q * 3, q * 3 + 3);
    const q_ = { actualMwh: 0, expectedMwh: 0, estimatedMwh: 0, hasData: qMonths.some(m => m) };
    qMonths.forEach(m => {
      q_.actualMwh += m ? Math.round(m.actualMwh) : 0;
      q_.expectedMwh += m ? Math.round(m.expectedMwh) : 0;
      q_.estimatedMwh += m ? Math.round(m.estimatedMwh) : 0;
    });
    q_.actVsExp = q_.expectedMwh ? q_.actualMwh / q_.expectedMwh : 0;
    q_.actVsEst = q_.estimatedMwh ? q_.actualMwh / q_.estimatedMwh : 0;
    quarters.push(q_);
  }
  return quarters;
}

