let miniPerfChartInstance = null;
function renderMiniPerfChart(labels, actualData, expectedData) {
  const canvas = document.getElementById("perfMiniChart");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (miniPerfChartInstance) {
    miniPerfChartInstance.destroy();
  }
  
  const defaultLabels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const defaultActs = [24, 38, 52, 68, 86, 94, 98, 90, 75, 58, 42, 26];
  const defaultExps = [28, 44, 58, 74, 90, 98, 104, 96, 82, 64, 46, 30];

  const chartLabels = (labels && labels.length) ? labels : defaultLabels;
  const bars = (actualData && actualData.length) ? actualData : defaultActs;
  const line = (expectedData && expectedData.length) ? expectedData : defaultExps;

  miniPerfChartInstance = new Chart(ctx, {
    data: {
      labels: chartLabels,
      datasets: [
        {
          type: "bar",
          label: "Actual",
          data: bars,
          backgroundColor: "#6B9BD2",
          hoverBackgroundColor: "#4680C4",
          borderRadius: 3,
          order: 2
        },
        {
          type: "bar",
          label: "Expected",
          data: line,
          backgroundColor: "#8CC69A",
          hoverBackgroundColor: "#5FAE73",
          borderRadius: 3,
          order: 1
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: {
        duration: 1200,
        easing: "easeOutQuart"
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          enabled: true,
          displayColors: false,
          callbacks: {
            title: (items) => items[0].label,
            label: (ctx) => `${ctx.dataset.label}: ${ctx.raw} MWh`
          }
        }
      },
      scales: {
        x: { display: true, ticks: { font: { size: 8 } }, grid: { display: false } },
        y: { display: true, min: 0, ticks: { font: { size: 8 } } }
      }
    }
  });
}

function updateDashboardCards(d, file) {
  if (!d) return;

  // 1. Data Ready card
  const readyName = document.getElementById("readyFileName");
  if (readyName) readyName.textContent = file ? file.name : (lastCsvFileName || (d.siteName + ".csv"));
  const readyMeta = document.getElementById("readyFileMeta");
  const monthCount = d.monthly ? d.monthly.filter(Boolean).length : 0;
  const dayCount = d.daily ? d.daily.length : 0;
  const fileSizeStr = file ? `${(file.size / (1024 * 1024)).toFixed(2)} MB` : "6.46 MB";
  if (readyMeta) {
    readyMeta.innerHTML = `<span>📅 ${dayCount} Data points</span> <span>•</span> <span>${monthCount} months</span> <span>•</span> <span>${fileSizeStr}</span>`;
  }

  // 2. Performance Summary Card
  const perfAct = document.getElementById("perfActualVal");
  if (perfAct) perfAct.textContent = num(d.actualMwh) + " MWh";
  const perfExp = document.getElementById("perfVsExpVal");
  if (perfExp) perfExp.textContent = pct(d.actVsExp);
  const perfEst = document.getElementById("perfVsEstVal");
  if (perfEst) perfEst.textContent = pct(d.actVsEst);

  // 3. Quick Summary Card
  const qsAc = document.getElementById("qsAcCapacity");
  if (qsAc) qsAc.textContent = (d.acSize != null && !isNaN(d.acSize)) ? `${d.acSize} MW` : "—";
  const qsDc = document.getElementById("qsDcCapacity");
  if (qsDc) qsDc.textContent = (d.dcSize != null && !isNaN(d.dcSize)) ? `${d.dcSize} MWp` : "—";
  const qsSite = document.getElementById("qsSiteLocation");
  if (qsSite) {
    const monthsCount = d.monthly ? d.monthly.filter(Boolean).length : null;
    qsSite.textContent = (monthsCount != null) ? monthsCount : "—";
  }
  const qsPeriod = document.getElementById("qsReportingPeriod");
  if (qsPeriod && d.firstMonth && d.reportMonth) {
    const monthName = MONTH_NAMES_FULL[d.reportMonth.getMonth()], year = d.reportMonth.getFullYear();
    const firstMonthName = MONTH_NAMES_FULL[d.firstMonth.getMonth()], firstYear = d.firstMonth.getFullYear();
    qsPeriod.textContent = (firstMonthName === monthName && firstYear === year) ? `${monthName} ${year}` : `${firstMonthName} \u2013 ${monthName} ${year}`;
  }

  // 4. Update and animate the mini chart with real data
  if (d.monthly) {
    const activeMonths = d.monthly.filter(Boolean);
    if (activeMonths.length) {
      const labels = activeMonths.map(m => MONTHS[m.monthIdx]);
      const acts = activeMonths.map(m => m.actualMwh ? Number(m.actualMwh.toFixed(1)) : 0);
      const exps = activeMonths.map(m => m.expectedMwh ? Number(m.expectedMwh.toFixed(1)) : 0);
      const perfChartContainer = document.getElementById("perfChartContainer");
      if (perfChartContainer) perfChartContainer.style.display = "";
      renderMiniPerfChart(labels, acts, exps);
    }
  }
}

function handleFile(file) {
  parseStatus.textContent = "Reading " + file.name + "\u2026";
  parseStatus.className = "status";
  const reader = new FileReader();
  reader.onload = () => {
    try {
      parsedData = parseDasCsv(reader.result);
      lastCsvFileName = file.name;
      parseStatus.innerHTML = "\u2705 Got it \u2014 looking good!";
      parseStatus.className = "status ok";
      renderSummary(parsedData);
      updateDashboardCards(parsedData, file);
      const emptyDropStateEl = document.getElementById("emptyDropState");
      const dataReadyHeaderEl = document.getElementById("dataReadyHeader");
      const fileInfoPillEl = document.getElementById("fileInfoPill");
      if (emptyDropStateEl) emptyDropStateEl.style.display = "none";
      if (dataReadyHeaderEl) dataReadyHeaderEl.style.display = "";
      if (fileInfoPillEl) fileInfoPillEl.style.display = "";
      locationInput.value = SITE_LOCATIONS[parsedData.siteKey] || parsedData.siteKey;
      generateBtn.disabled = false;
      generateBtn.innerHTML = "<span>+ Generate Report &gt;</span>";
      generateBtn.classList.add("ready");
      resetGenerateUI();
    } catch (err) {
      parseStatus.textContent = "Hmm, that didn't parse: " + err.message;
      parseStatus.className = "status error";
      summaryBox.innerHTML = '<div class="empty-hint">Fix the file and try again \u2014 I believe in you \ud83d\udcaa</div>';
      generateBtn.disabled = true;
      generateBtn.innerHTML = "<span>Upload a CSV first</span>";
    }
  };
  reader.onerror = () => { parseStatus.textContent = "Could not read that file."; parseStatus.className = "status error"; };
  reader.readAsText(file);
}

function renderSummary(d) {
  const monthName = MONTH_NAMES_FULL[d.reportMonth.getMonth()], year = d.reportMonth.getFullYear();
  const firstMonthName = MONTH_NAMES_FULL[d.firstMonth.getMonth()], firstYear = d.firstMonth.getFullYear();
  const periodLabel = (firstMonthName === monthName && firstYear === year) ? `${monthName} ${year}` : `${firstMonthName} ${firstYear} \u2013 ${monthName} ${year}`;
  const row = (l, v) => `<div class="row"><span class="label">${l}</span><span class="value">${v}</span></div>`;
  summaryBox.innerHTML = `<div class="summary">
    ${row("Site", escXml(d.siteName))}${row("Size", `${d.dcSize} MWp / ${d.acSize} MW`)}${row("Period", periodLabel)}
    ${row("Months of data", d.monthly.filter(Boolean).length)}${row("Days of data", d.daily.length)}
    ${row("Actual (YTD)", num(d.actualMwh) + " MWh")}${row("Act vs Expected (YTD)", pct(d.actVsExp))}${row("Act vs Estimated (YTD)", pct(d.actVsEst))}
  </div>`;
}

