/* ---------- 6. Report history (IndexedDB: metadata + downloadable .docx blob) ---------- */
const HIST_DB_NAME = "pse_report_history_db", HIST_STORE = "reports";
function openHistDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(HIST_DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(HIST_STORE)) {
        const store = db.createObjectStore(HIST_STORE, { keyPath: "id" });
        store.createIndex("timestamp", "timestamp");
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function saveHistoryRecord(record) {
  try {
    const db = await openHistDb();
    record.id = "r_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8);
    await new Promise((resolve, reject) => {
      const tx = db.transaction(HIST_STORE, "readwrite");
      tx.objectStore(HIST_STORE).put(record);
      tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
    });
  } catch (err) { console.error("History save failed:", err); }
}
async function listHistoryRecords() {
  try {
    const db = await openHistDb();
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(HIST_STORE, "readonly");
      const req = tx.objectStore(HIST_STORE).getAll();
      req.onsuccess = () => resolve((req.result || []).sort((a, b) => b.timestamp - a.timestamp));
      req.onerror = () => reject(req.error);
    });
  } catch (err) { console.error("History read failed:", err); return []; }
}
async function deleteHistoryRecord(id) {
  try {
    const db = await openHistDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(HIST_STORE, "readwrite");
      tx.objectStore(HIST_STORE).delete(id);
      tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
    });
  } catch (err) { console.error("History delete failed:", err); }
}

const historyBtn = document.getElementById("historyBtn");
const historyPanel = document.getElementById("historyPanel");
const historyOverlay = document.getElementById("historyOverlay");
const historyClose = document.getElementById("historyClose");
const historyBody = document.getElementById("historyBody");
const historyCount = document.getElementById("historyCount");
const historySearch = document.getElementById("historySearch");
const historyClearAll = document.getElementById("historyClearAll");

function openHistory() { historyPanel.classList.add("open"); historyOverlay.classList.add("open"); }
function closeHistory() { historyPanel.classList.remove("open"); historyOverlay.classList.remove("open"); }
historyBtn.addEventListener("click", () => { openHistory(); refreshHistoryUI(); });
historyClose.addEventListener("click", closeHistory);
historyOverlay.addEventListener("click", closeHistory);

let allHistoryRecords = [];
function renderHistoryList(records) {
  if (!records.length) {
    historyBody.innerHTML = '<div class="empty-hint">No reports generated yet.</div>';
    return;
  }
  historyBody.innerHTML = records.map(r => {
    const dt = new Date(r.timestamp);
    return `<div class="hist-row" data-id="${r.id}">
      <div class="hr-top"><span class="hr-site">${escXml(r.site || "Untitled site")}</span><span class="hr-date">${dt.toLocaleDateString()} ${dt.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}</span></div>
      <div class="hr-meta">${escXml(r.location || "")}${r.location ? " &middot; " : ""}${escXml(r.sourceFileName || "")}</div>
      <div class="hr-actions">
        <button class="hr-btn" data-action="redownload">&#11015; Re-download</button>
        <button class="hr-btn danger" data-action="delete">Delete</button>
      </div>
    </div>`;
  }).join("");
}
function applyHistorySearch() {
  const q = (historySearch.value || "").trim().toLowerCase();
  if (!q) { renderHistoryList(allHistoryRecords); return; }
  const filtered = allHistoryRecords.filter(r => {
    const haystack = [r.site, r.location, r.sourceFileName].filter(Boolean).join(" ").toLowerCase();
    return haystack.includes(q);
  });
  if (!filtered.length) {
    historyBody.innerHTML = '<div class="empty-hint">No reports match your search.</div>';
    return;
  }
  renderHistoryList(filtered);
}
async function refreshHistoryUI() {
  allHistoryRecords = await listHistoryRecords();
  historyCount.style.display = allHistoryRecords.length ? "flex" : "none";
  historyCount.textContent = allHistoryRecords.length;
  applyHistorySearch();
}
historySearch.addEventListener("input", applyHistorySearch);
historyClearAll.addEventListener("click", async () => {
  if (!allHistoryRecords.length) return;
  if (!confirm("Clear all report history? This cannot be undone.")) return;
  for (const r of allHistoryRecords) { await deleteHistoryRecord(r.id); }
  historySearch.value = "";
  await refreshHistoryUI();
});
historyBody.addEventListener("click", async e => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const row = btn.closest(".hist-row");
  const id = row.dataset.id;
  if (btn.dataset.action === "delete") {
    await deleteHistoryRecord(id);
    await refreshHistoryUI();
  } else if (btn.dataset.action === "redownload") {
    const records = await listHistoryRecords();
    const rec = records.find(r => r.id === id);
    if (rec && rec.blob) downloadBlob(rec.blob, rec.fileName || "report.docx");
  }
});
refreshHistoryUI();
